#include <pthread.h>
#include <stdio.h>
int main() {
    pthread_mutexattr_t attr;
    if (pthread_mutexattr_init(&attr) != 0) {
        printf("Error initializing mutex attribute\n");
        return 1;
    }
    int ret = pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_PRIVATE);
    if (ret == 0) {
        printf("Process-shared attribute set successfully\n");
    } else {
        printf("Error setting process-shared attribute: %d\n", ret);
    }
    pthread_mutexattr_destroy(&attr);
    return 0;
}
